package com.nexusdrive.metadata.entity;import jakarta.persistence.*;import java.time.Instant;import java.util.*;@Entity@Table(name="file_metadata")public class FileMetadata{@Id private UUID id;@Column(name="owner_id",nullable=false)private UUID ownerId;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="folder_id")private Folder folder;@Column(nullable=false)private String filename;@Column(name="mime_type",nullable=false)private String mimeType;@Column(name="size_bytes",nullable=false)private long sizeBytes;@Column(name="content_hash",length=64)private String contentHash;@Column(name="encryption_key_ref",length=100)private String encryptionKeyRef;@Enumerated(EnumType.STRING)@Column(nullable=false)private Status status;@Column(columnDefinition="text[]")private String[] tags=new String[0];@Column(name="expected_chunks",nullable=false)private int expectedChunks;@Column(name="created_at",nullable=false)private Instant createdAt;@Column(name="updated_at",nullable=false)private Instant updatedAt;public enum Status{UPLOADING,ACTIVE,DELETED}@PrePersist void pre(){if(id==null)id=UUID.randomUUID();createdAt=updatedAt=Instant.now();if(status==null)status=Status.UPLOADING;}@PreUpdate void upd(){updatedAt=Instant.now();}public UUID getId(){return id;}public UUID getOwnerId(){return ownerId;}public void setOwnerId(UUID v){ownerId=v;}public Folder getFolder(){return folder;}public void setFolder(Folder v){folder=v;}public String getFilename(){return filename;}public void setFilename(String v){filename=v;}public String getMimeType(){return mimeType;}public void setMimeType(String v){mimeType=v;}public long getSizeBytes(){return sizeBytes;}public void setSizeBytes(long v){sizeBytes=v;}public String getContentHash(){return contentHash;}public void setContentHash(String v){contentHash=v;}public String getEncryptionKeyRef(){return encryptionKeyRef;}public void setEncryptionKeyRef(String v){encryptionKeyRef=v;}public Status getStatus(){return status;}public void setStatus(Status v){status=v;}public String[] getTags(){return tags;}public void setTags(String[] v){tags=v;}public int getExpectedChunks(){return expectedChunks;}public void setExpectedChunks(int v){expectedChunks=v;}public Instant getCreatedAt(){return createdAt;}public Instant getUpdatedAt(){return updatedAt;}}
